#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets up one deployment of Logitland: `bash scripts/setup-deploy.sh staging` first, `… production` before the first release.
# It creates the Cloudflare resources (D1, queues, the avatar bucket), writes the database ID into apps/backend/wrangler.jsonc, and puts every
# value the deploy workflows read into the GitHub environment of the same name, with its deployment rules. It deploys
# nothing and deletes nothing: the first run of the deploy workflow creates the Workers, routes and Custom Domain.
# Values are kept in the same private file the Discord app wizard writes, so a re-run offers them back.

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

DEPLOY_ENV="${1:-}"
case "$DEPLOY_ENV" in
  staging)
    HOST=staging.logit.land
    ENV_FILE="${RELAY_STAGING_ENV_FILE:-$HOME/.config/logitland/relay-staging.env}"
    APP_NAME="Logan staging"
    APP_WIZARD=scripts/setup-staging-app.sh
    D1_NAME=logitland-staging
    D1_PLACEHOLDER=SETUP_DEPLOY_STAGING_D1_ID
    QUEUE=logitland-staging-deliveries
    BUCKET=logitland-staging-avatars
    ;;
  production)
    HOST=logit.land
    ENV_FILE="${RELAY_ENV_FILE:-$HOME/.config/logitland/relay.env}"
    APP_NAME="Logan"
    APP_WIZARD=scripts/setup-relay-bot.sh
    D1_NAME=logitland
    D1_PLACEHOLDER=SETUP_DEPLOY_PRODUCTION_D1_ID
    QUEUE=logitland-deliveries
    BUCKET=logitland-avatars
    ;;
  *)
    echo "Usage: bash scripts/setup-deploy.sh staging|production" >&2
    exit 2
    ;;
esac
GH_ENV="$DEPLOY_ENV"
ZONE=logit.land
DISCORD_KEYS=(DISCORD_APPLICATION_ID DISCORD_PUBLIC_KEY DISCORD_BOT_TOKEN DISCORD_CLIENT_ID DISCORD_CLIENT_SECRET)
RELAY_KEYS=(RELAY_SECRET_KEY INTERNAL_TOKEN IP_HASH_KEY SESSION_SECRET)
mkdir -p "$(dirname "$ENV_FILE")"
touch "$ENV_FILE" && chmod 600 "$ENV_FILE"

random_secret() { node -e "console.log(crypto.getRandomValues(Buffer.alloc(32)).toString('base64'))"; }
# value KEY prints KEY from ENV_FILE, or nothing.
value() { _existing "$1" || true; }
# cf PATH prints Cloudflare's JSON answer for a GET of PATH, with the token from stage 2.
cf() { curl -fsS -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" "https://api.cloudflare.com/client/v4$1"; }
# json EXPR evaluates EXPR against the JSON on stdin (as `j`) and prints the result, if any.
json() { node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>{const j=JSON.parse(s);const v=($1);if(v!==undefined&&v!==null&&v!=='')console.log(v)})"; }
# wr ARGS runs this checkout's wrangler in apps/backend, as the token from stage 2.
wr() {
  (cd "$ROOT/apps/backend" && CLOUDFLARE_API_TOKEN="$CLOUDFLARE_API_TOKEN" CLOUDFLARE_ACCOUNT_ID="$CLOUDFLARE_ACCOUNT_ID" \
    WRANGLER_SEND_METRICS=false pnpm exec wrangler "$@")
}
gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }
# env_secret NAME VALUE and env_var NAME VALUE write to the GitHub environment the deploy workflows read.
env_secret() {
  if printf '%s' "$2" | gh secret set "$1" --env "$GH_ENV" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$1")
    printf '  %s✓ set%s secret %s\n' "$GREEN" "$RESET" "$1"
  else
    SKIPPED+=("secret $1 on the GitHub $GH_ENV environment (gh secret set $1 --env $GH_ENV)")
    warn "couldn't set secret $1"
  fi
}
env_var() {
  if gh variable set "$1" --env "$GH_ENV" --body "$2" >/dev/null 2>&1; then
    printf '  %s✓ set%s variable %s\n' "$GREEN" "$RESET" "$1"
  else
    SKIPPED+=("variable $1 on the GitHub $GH_ENV environment (gh variable set $1 --env $GH_ENV)")
    warn "couldn't set variable $1"
  fi
}

TOTAL_STAGES=9

banner "Logitland $DEPLOY_ENV deploy · $HOST"

stage "Discord application: $APP_NAME"
missing=()
for key in "${DISCORD_KEYS[@]}"; do [[ -n "$(value "$key")" ]] || missing+=("$key"); done
if (( ${#missing[@]} )); then
  warn "$ENV_FILE has no ${missing[*]} yet. $APP_WIZARD sets up $APP_NAME and writes them."
  confirm "Run $APP_WIZARD now?" && bash "$APP_WIZARD"
  _clear
  for key in "${DISCORD_KEYS[@]}"; do
    [[ -n "$(value "$key")" ]] || { warn "$ENV_FILE still has no $key. Run $APP_WIZARD, then this wizard again."; exit 1; }
  done
fi
note "$APP_NAME's credentials are in $ENV_FILE."
if [[ "$DEPLOY_ENV" == production ]]; then
  open_url "https://discord.com/developers/applications/$(value DISCORD_APPLICATION_ID)/oauth2"
  step "Under Redirects, make sure https://logit.land/auth/callback is listed. Save Changes if you added it."
else
  note "$APP_WIZARD already added https://staging.logit.land/auth/callback to its OAuth2 redirects."
fi
pause "Press Enter to continue"

stage "Cloudflare API token"
say "The deploy workflow's token: the Logitland account and the logit.land zone, nothing else."
if [[ -n "$(value CLOUDFLARE_API_TOKEN)" ]] && confirm "$ENV_FILE already has a Cloudflare token. Use it?"; then
  CLOUDFLARE_API_TOKEN="$(value CLOUDFLARE_API_TOKEN)"
  REUSE_TOKEN=1
else
  REUSE_TOKEN=""
fi
if [[ -z "$REUSE_TOKEN" ]]; then
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create Token → Create Custom Token. Name: Logitland deploy."
  step "Permissions, one row each:"
  step "  Account · Workers Scripts · Edit"
  step "  Account · D1 · Edit"
  step "  Account · Queues · Edit"
  step "  Account · Workers R2 Storage · Edit"
  step "  Account · Account Settings · Read"
  step "  Zone · Workers Routes · Edit"
  step "  Zone · DNS · Edit   (the first deploy creates $HOST's record)"
  step "  Zone · Zone · Read"
  step "Account Resources: Include → your account. Zone Resources: Include → Specific zone → $ZONE."
  step "Continue to summary → Create Token → copy it (shown once)."
  ask_secret CLOUDFLARE_API_TOKEN "Paste the token (hidden):"
fi
CLOUDFLARE_ACCOUNT_ID="$(value CLOUDFLARE_ACCOUNT_ID)"
[[ -n "$CLOUDFLARE_ACCOUNT_ID" ]] || CLOUDFLARE_ACCOUNT_ID="$(cf /accounts | json 'j.result.length === 1 ? j.result[0].id : undefined' || true)"
if [[ -z "$CLOUDFLARE_ACCOUNT_ID" ]]; then
  open_url "https://dash.cloudflare.com"
  step "Open the Logitland account; its ID is in the address bar after dash.cloudflare.com/."
  ask CLOUDFLARE_ACCOUNT_ID "Paste the account ID:"
fi
# A user token verifies at /user/tokens/verify, an account token (Manage Account → API Tokens) at its account's endpoint.
if [[ "$(cf /user/tokens/verify | json 'j.result.status' || true)" != active ]] &&
  [[ "$(cf "/accounts/$CLOUDFLARE_ACCOUNT_ID/tokens/verify" | json 'j.result.status' || true)" != active ]]; then
  warn "Cloudflare doesn't accept that token for account $CLOUDFLARE_ACCOUNT_ID. Check you copied all of it and the account ID, then run this wizard again."
  exit 1
fi
write_env CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"

stage "Hostname: $HOST"
say "The web app owns $HOST as a Custom Domain; Worker routes send the relay's paths on it (/v1, /mcp, /oauth2, …) to the relay."
ZONE_ID="$(cf "/zones?name=$ZONE" | json 'j.result[0]?.id' || true)"
[[ -n "$ZONE_ID" ]] || { warn "The token can't see the $ZONE zone: give it Zone · Zone · Read on $ZONE, then run this again."; exit 1; }
if [[ -n "$(cf "/accounts/$CLOUDFLARE_ACCOUNT_ID/workers/domains?hostname=$HOST" | json 'j.result[0]?.service' || true)" ]]; then
  note "$HOST is already a Workers Custom Domain. Nothing to do."
else
  records="$(cf "/zones/$ZONE_ID/dns_records?name=$HOST" | json 'j.result.map((r) => r.type + " " + r.content).join("\n")' || true)"
  if [[ -n "$records" ]]; then
    warn "$HOST already has DNS records, and Cloudflare won't put a Custom Domain over them:"
    while IFS= read -r line; do note "    $line"; done <<<"$records"
    open_url "https://dash.cloudflare.com/$CLOUDFLARE_ACCOUNT_ID/$ZONE/dns/records"
    step "Delete those records for $HOST. Whatever answers there now goes offline until the first deploy."
  else
    note "$HOST has no DNS records yet: the first deploy creates its record and certificate."
  fi
fi
pause "Press Enter to continue"

stage "Database, queues and avatar storage"
D1_ID="$(wr d1 list --json | json "j.find((d) => d.name === '$D1_NAME')?.uuid" || true)"
if [[ -z "$D1_ID" ]]; then
  wr d1 create "$D1_NAME" </dev/null >/dev/null
  D1_ID="$(wr d1 list --json | json "j.find((d) => d.name === '$D1_NAME')?.uuid")"
  printf '  %s✓ created%s D1 database %s\n' "$GREEN" "$RESET" "$D1_NAME"
else
  note "D1 database $D1_NAME exists."
fi
for queue in "$QUEUE" "$QUEUE-dlq"; do
  if wr queues info "$queue" >/dev/null 2>&1; then
    note "Queue $queue exists."
  else
    wr queues create "$queue" >/dev/null
    printf '  %s✓ created%s queue %s\n' "$GREEN" "$RESET" "$queue"
  fi
done
if wr r2 bucket info "$BUCKET" >/dev/null 2>&1; then
  note "R2 bucket $BUCKET exists."
elif wr r2 bucket create "$BUCKET" >/dev/null; then
  printf '  %s✓ created%s R2 bucket %s\n' "$GREEN" "$RESET" "$BUCKET"
else
  warn "Couldn't create R2 bucket $BUCKET. Give the token Account · Workers R2 Storage · Edit, then run this wizard again."
  exit 1
fi
if grep -q "$D1_PLACEHOLDER" apps/backend/wrangler.jsonc; then
  node -e 'const fs = require("fs"); const [file, from, to] = process.argv.slice(1); fs.writeFileSync(file, fs.readFileSync(file, "utf8").replace(from, to));' \
    apps/backend/wrangler.jsonc "$D1_PLACEHOLDER" "$D1_ID"
  printf '  %s✓ wrote%s the database ID → apps/backend/wrangler.jsonc (committed in the last stage)\n' "$GREEN" "$RESET"
elif ! grep -q "$D1_ID" apps/backend/wrangler.jsonc; then
  warn "apps/backend/wrangler.jsonc names another $DEPLOY_ENV database than $D1_NAME ($D1_ID). Check env.$DEPLOY_ENV.d1_databases."
fi

stage "Moderation and errors"
TYPESAFE_API_KEY="$(value TYPESAFE_API_KEY)"
if [[ -z "$TYPESAFE_API_KEY" && -s "$HOME/.config/logitland/relay.env" ]]; then
  TYPESAFE_API_KEY="$(ENV_FILE="$HOME/.config/logitland/relay.env" _existing TYPESAFE_API_KEY || true)"
fi
if [[ -z "$TYPESAFE_API_KEY" && -s "$HOME/.config/typesafe-api-key" ]]; then
  TYPESAFE_API_KEY="$(tr -d '\n' <"$HOME/.config/typesafe-api-key")"
fi
if [[ -n "$TYPESAFE_API_KEY" ]]; then
  note "Using the TypeSafe key you already have. For a separate $DEPLOY_ENV key, change TYPESAFE_API_KEY in $ENV_FILE and re-run."
else
  open_url "https://console.typesafe.ai"
  step "Create an API key for Logitland $DEPLOY_ENV and copy it."
  ask_secret TYPESAFE_API_KEY "Paste the TypeSafe API key (hidden):"
fi
write_env TYPESAFE_API_KEY "$TYPESAFE_API_KEY"
say "Sentry is optional: without a DSN the relay sends no errors anywhere."
ask SENTRY_DSN "Sentry DSN for $DEPLOY_ENV (Enter to skip):"
[[ -z "$SENTRY_DSN" ]] || write_env SENTRY_DSN "$SENTRY_DSN"

stage "The relay's own keys"
say "Random values the relay and web app share or keep to themselves; nothing to copy."
for key in "${RELAY_KEYS[@]}"; do
  if [[ -n "$(value "$key")" ]]; then note "$key already set; keeping it."; continue; fi
  write_env "$key" "$(random_secret)"
done
warn "Back up $ENV_FILE: GitHub never shows a secret again, and losing RELAY_SECRET_KEY makes stored webhooks unreadable."

stage "GitHub environment: $GH_ENV"
gh_ready || { warn "gh isn't signed in: run gh auth login, then this wizard again. Everything so far is saved."; exit 1; }
if [[ "$DEPLOY_ENV" == staging ]]; then
  say "Only main may deploy staging."
  rules='{"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}'
  policies=("branch main")
else
  say "Only release tags may deploy production, and each deploy waits for your approval."
  rules="{\"reviewers\":[{\"type\":\"User\",\"id\":$(gh api user -q .id)}],\"prevent_self_review\":false,\"deployment_branch_policy\":{\"protected_branches\":false,\"custom_branch_policies\":true}}"
  policies=("tag @logitland/web@*" "tag @logitland/backend@*")
fi
gh api -X PUT "repos/{owner}/{repo}/environments/$GH_ENV" --input - <<<"$rules" >/dev/null
for policy in "${policies[@]}"; do
  # Answers 4xx when the rule is already there.
  gh api -X POST "repos/{owner}/{repo}/environments/$GH_ENV/deployment-branch-policies" \
    -f type="${policy%% *}" -f name="${policy#* }" >/dev/null 2>&1 || true
done
printf '  %s✓ set%s the %s environment'"'"'s rules\n' "$GREEN" "$RESET" "$GH_ENV"
env_var CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
env_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
for key in "${DISCORD_KEYS[@]}" TYPESAFE_API_KEY "${RELAY_KEYS[@]}"; do env_secret "$key" "$(value "$key")"; done
[[ -z "$(value SENTRY_DSN)" ]] || env_secret SENTRY_DSN "$(value SENTRY_DSN)"
if [[ "$DEPLOY_ENV" == staging ]]; then
  say "The release workflow opens the \"chore: version packages\" pull request, which GitHub Actions may not do by default."
  if confirm "Allow GitHub Actions to create pull requests in this repository?"; then
    if gh api -X PUT "repos/{owner}/{repo}/actions/permissions/workflow" \
      -f default_workflow_permissions=read -F can_approve_pull_request_reviews=true >/dev/null 2>&1; then
      printf '  %s✓ allowed%s GitHub Actions to create pull requests\n' "$GREEN" "$RESET"
    else
      SKIPPED+=("Settings → Actions → General → Allow GitHub Actions to create and approve pull requests")
      warn "couldn't change it; the organization may decide this setting"
    fi
  fi
else
  note "You're the required reviewer. Add others under Settings → Environments → production."
fi

stage "Interactions Endpoint URL"
APP_URL="https://discord.com/developers/applications/$(value DISCORD_APPLICATION_ID)/information"
if [[ "$DEPLOY_ENV" == staging ]]; then
  say "Without an Interactions Endpoint URL, Discord sends /consent and its buttons over the Gateway, which the relay answers."
  say "Local dev runs as Logan staging too, so a URL here would send dev's /consent to staging.logit.land instead."
  note "Recommended: leave it unset. The dashboard's Setup page then lists it as failing on staging; that's expected."
  if confirm "Set one on Logan staging anyway?"; then
    step "After the first staging deploy (Discord pings the URL when you save):"
    step "General Information → Interactions Endpoint URL → https://staging.logit.land/v1/discord/interactions → Save Changes."
    open_url "$APP_URL"
  fi
else
  say "Logan answers over the Gateway until it has an Interactions Endpoint URL."
  step "After the first production deploy (Discord pings the URL when you save):"
  step "General Information → Interactions Endpoint URL → https://logit.land/v1/discord/interactions → Save Changes."
  note "Run this wizard's last stage again later, or open $APP_URL."
fi
pause "Press Enter to continue"

stage "Deploy"
if ! git diff --quiet -- apps/backend/wrangler.jsonc; then
  git --no-pager diff -- apps/backend/wrangler.jsonc
  if confirm "Commit the $DEPLOY_ENV database ID?"; then
    git commit -q -m "chore(backend): add the $DEPLOY_ENV database ID" -- apps/backend/wrangler.jsonc
    printf '  %s✓ committed%s apps/backend/wrangler.jsonc; push it with the rest of your branch\n' "$GREEN" "$RESET"
  fi
fi
if [[ "$DEPLOY_ENV" == staging ]]; then
  say "Every push to main now deploys https://staging.logit.land (Actions → Deploy staging)."
  say "Once it's green: sign in, open the admin dashboard's Setup page, and work through what isn't."
else
  say "Production deploys only a release, by hand:"
  step "Merge the \"chore: version packages\" pull request; that tags the release."
